input.command:
# Check parent directories for .acm/destination.md (up to 4 levels)
$current = Get-Location
$levels = @()
$path = $current.Path
for ($i = 0; $i -lt 4; $i++) {
    $parent = Split-Path -Parent $path
    if (-not $parent -or $parent -eq $path) { break }
    $acmPath = Join-Path $parent ".acm"
    $destPath = Join-Path $acmPath "destination.md"
    $rootMarker = Join-Path $parent ".acm-root"

    if (Test-Path $destPath) {
        $levels += "Found .acm/destination.md at: $parent"
    }
    if (Test-Path $rootMarker) {
        $levels += "Found .acm-root marker at: $parent (stopping traversal)"
        break
    }
    $path = $parent
}
if ($levels.Count -eq 0) {
    "No parent .acm/destination.md found"
} else {
    $levels -join "`n"
}
